/* El contenedor con scroll, fondo Cold White y padding lo aporta el shell
   (`.bwcnt` del HTML aprobado); esta pantalla solo pinta el contenido. */
.page {
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin-top: 0;
  margin-bottom: 3px;
}

.subtitle {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin-top: 0;
  margin-bottom: 16px;
  max-width: 560px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
  margin: 0;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

/* El mock pinta el input en blanco puro; sin token de blanco, se usa el neutro
   de superficie clara más cercano. */
.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: 13px;
  color: var(--bw-deep-steel);
  outline: none;
  font-family: var(--bw-font-body);
  background: var(--bw-surface-mist);
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.btnPrimary {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-on-dark-hover); /* sin token de blanco puro: blanco al 90% del shell */
  font-size: 13px;
  font-weight: 500;
  font-family: var(--bw-font-body);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  transition: opacity 0.12s;
}

.btnPrimary:hover:not(:disabled) {
  opacity: 0.88;
}

.btnDisabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.threadCount {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.errorAlert {
  padding: 12px 16px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 6px;
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
}

.loading {
  padding: 24px;
  text-align: center;
  color: var(--bw-steel-mist);
  font-size: 14px;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

/* El mock pinta los botones de página en blanco puro; sin token de blanco, se
   usa el neutro de superficie clara más cercano. */
.pageBtn {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--bw-font-body);
  transition: border-color 0.12s, color 0.12s;
}

.pageBtn:hover:not(:disabled):not(.pageBtnActive) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtnActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-on-dark-hover);
  cursor: default;
}

.pageBtn:disabled {
  color: var(--bw-input-placeholder);
  cursor: default;
}

