import { useEffect, useState, type FormEvent } from 'react';
import { fetchThreadPage, pageCount, sanitizeSearch, type ThreadSummary } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * Extrae el error de verdad para F-128. PostgREST no lanza `Error`: rechaza con
 * un objeto plano `{ code, message }`, y `String(e)` daría `[object Object]`.
 */
function describeError(e: unknown): string {
  if (e instanceof Error) return e.message || 'Error';
  if (typeof e === 'object' && e !== null) {
    const o = e as Record<string, unknown>;
    const code = typeof o.code === 'string' && o.code ? o.code : '';
    const message = typeof o.message === 'string' && o.message ? o.message : '';
    if (code || message) return [code, message].filter(Boolean).join(': ');
  }
  const s = String(e);
  return s === '[object Object]' ? 'error desconocido' : s;
}

/**
 * MSG-01 · Lista de Hilos — pantalla, no presentación.
 *
 * Posee el estado de búsqueda y de página, llama a `fetchThreadPage` con el
 * `orgId` del perfil y pinta la lista a través de `ThreadList`.
 */
export function Messages({
  profile,
  now = new Date(),
  onOpenThread,
}: {
  profile: MemberProfile;
  now?: Date;
  onOpenThread?: (threadId: string) => void;
}) {
  // F-118: el shell cablea onOpenThread desde App.tsx; MSG-02 no existe en el
  // alcance del MVP, así que esta prop se recibe y se ignora. Abrir un hilo no
  // lleva a ningún sitio en esta entrega.
  void onOpenThread;

  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((res) => {
        if (cancelled) return;
        setThreads(res.threads);
        setTotal(res.total);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(e);
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  const submitSearch = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setSearch(sanitizeSearch(searchInput));
    setPage(1);
  };

  // MSG-02 está fuera del alcance: se recibe el id y no se hace nada con él.
  const handleOpen = (_id: string) => {
    /* sin destino en el MVP */
  };

  const pages = pageCount(total);

  return (
    <div className={styles.page}>
      <div className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</div>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
      </p>

      <div className={styles.actionsBar}>
        <form className={styles.searchWrap} onSubmit={submitSearch}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            className={styles.searchInput}
            type="text"
            placeholder="Buscar por nombre de organización..."
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
          />
        </form>
        <button
          type="button"
          className={`${styles.btnPrimary} ${styles.btnDisabled}`}
          disabled
          title="Fuera del MVP: el Directorio de Organizaciones se abre en una pantalla posterior"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span className={styles.threadCount}>
          {total} hilos · Página {page} de {pages}
        </span>
      </div>

      {error ? (
        <div className={styles.errorAlert} role="alert">
          No se pudieron cargar los hilos. {describeError(error)}
        </div>
      ) : loading && threads.length === 0 ? (
        <p className={styles.loading}>Cargando hilos…</p>
      ) : (
        <ThreadList threads={threads} now={now} onOpen={handleOpen} />
      )}

      {!error && total > 0 && (
        <div className={styles.pagination}>
          <button
            type="button"
            className={styles.pageBtn}
            aria-label="Página anterior"
            disabled={page <= 1}
            onClick={() => setPage(page - 1)}
          >
            ‹
          </button>
          {Array.from({ length: pages }, (_, i) => i + 1).map((n) => (
            <button
              key={n}
              type="button"
              className={`${styles.pageBtn} ${n === page ? styles.pageBtnActive : ''}`}
              aria-label={`Página ${n}`}
              aria-current={n === page ? 'page' : undefined}
              onClick={() => setPage(n)}
            >
              {n}
            </button>
          ))}
          <button
            type="button"
            className={styles.pageBtn}
            aria-label="Página siguiente"
            disabled={page >= pages}
            onClick={() => setPage(page + 1)}
          >
            ›
          </button>
        </div>
      )}
    </div>
  );
}

