/* La tarjeta y el botón del estado vacío son blancos en el mock aprobado; el
   sistema de diseño no tiene token de blanco puro, así que se usa el neutro de
   superficie clara más cercano: --bw-surface-mist. */
.list {
  padding: 0;
  margin: 0;
  list-style: none;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}
.row:last-child {
  border-bottom: none;
}

/* F-131: el botón vive DENTRO del <li>. El <li> conserva su rol `listitem` y es
   este botón el que lleva el nombre accesible del hilo (la contraparte). */
.rowButton {
  width: 100%;
  background: none;
  border: none;
  cursor: pointer;
  padding: 14px 18px;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  text-align: left;
  font-family: var(--bw-font-body);
  transition: background 0.1s;
}
.rowButton:hover {
  background: var(--bw-row-hover-tint);
}

.threadTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.countryBadge {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  flex-shrink: 0;
}

.tsRow {
  display: flex;
  align-items: center;
  gap: 6px;
  justify-content: flex-end;
  white-space: nowrap;
}

.timestamp {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.threadBot {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  font-size: 12px;
  color: var(--bw-steel-mist);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* El borde azul del mock es rgba(37,99,235,.2) y no tiene token;
   --bw-chip-active-border (.3) es el más cercano. */
.stateNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}
.stateInfo {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}
.stateWarn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}
.stateSuccess {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}
.stateClosed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

.empty {
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  padding: 48px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
}

.emptyText {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  max-width: 420px;
}

.emptyHint {
  font-size: 12px;
  color: var(--bw-input-placeholder);
}

