import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

const STATE_CLASS: Record<StateTone, string> = {
  neutral: styles.stateNeutral,
  info: styles.stateInfo,
  warn: styles.stateWarn,
  success: styles.stateSuccess,
  closed: styles.stateClosed,
};

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Recibe las filas ya ordenadas por el servidor y las pinta en ese orden.
 * Cada hilo va en un `<li>` que conserva su rol `listitem` (F-131): la fila es
 * pulsable gracias a un `<button>` DENTRO del `<li>`, nunca poniendo un `role`
 * encima — un `role="button"` sobre el `<li>` sustituiría al implícito y la
 * consulta por `listitem` dejaría de encontrarlo.
 */
export function ThreadList({
  threads,
  now,
  onOpen,
}: {
  threads: ThreadSummary[];
  now?: Date;
  onOpen: (id: string) => void;
}) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        <button type="button" className={`${styles.btnPrimary} ${styles.btnDisabled}`} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyHint}>El Directorio queda fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((t) => {
        const tone = stateTone(t.state);
        return (
          <li key={t.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowButton}
              aria-label={t.counterpartyName}
              onClick={() => onOpen(t.id)}
            >
              <span className={styles.threadTop}>
                <span className={styles.orgName}>{t.counterpartyName}</span>
                <span className={styles.countryBadge}>{t.counterpartyCountry}</span>
              </span>
              <span className={styles.tsRow}>
                <span className={styles.timestamp}>{relativeTime(t.lastItemAt, now)}</span>
              </span>
              <span className={styles.threadBot}>
                <span className={styles.preview}>{previewLabel(t.lastItem)}</span>
                <span className={`${styles.stateBadge} ${STATE_CLASS[tone]}`}>{t.state}</span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
